import{_ as e,o as a,c as o,a3 as r}from"./chunks/framework.B5WAEDB7.js";const f=JSON.parse('{"title":"Starting a flow via a button from an entry","description":"Use a field of type \\"Internal Link\\" to show a button that starts a flow tied to the entry.","frontmatter":{"title":"Starting a flow via a button from an entry","description":"Use a field of type \\"Internal Link\\" to show a button that starts a flow tied to the entry."},"headers":[],"relativePath":"en/grids/flow-button.md","filePath":"en/grids/flow-button.md","lastUpdated":1787319236000}'),n={name:"en/grids/flow-button.md"};function i(s,t,l,h,d,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="starting-a-flow-via-a-button-from-an-entry" tabindex="-1">Starting a flow via a button from an entry <a class="header-anchor" href="#starting-a-flow-via-a-button-from-an-entry" aria-label="Permalink to &quot;Starting a flow via a button from an entry&quot;">​</a></h1><p>A field of type <strong>Internal Link</strong> can point not only to a Grid, a form, or a page, but also to a <strong>link</strong> — the share link of a form or the start link of a flow. A value like that isn&#39;t displayed as text, but as a <strong>button</strong>. When someone clicks it, the target opens and learns <strong>which entry</strong> the click came from.</p><p>That&#39;s what sets this apart from a plain <a href="/en/referenz/spaltentypen#weblink">weblink field</a>: a weblink just opens the stored address. The button from an Internal Link additionally passes along the reference to the entry.</p><h2 id="requirement" tabindex="-1">Requirement <a class="header-anchor" href="#requirement" aria-label="Permalink to &quot;Requirement&quot;">​</a></h2><p>A flow with the <strong>Show page</strong> trigger. This trigger provides the start link that the field can point to.</p><p>→ <a href="/en/flows/trigger#show-page">Triggers</a></p><div class="tip custom-block"><p class="custom-block-title">Also works with forms</p><p>It works the same way with a form&#39;s <a href="/en/formulare/formular-teilen">share link</a>. The button isn&#39;t limited to flows in that case.</p></div><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><ol><li>Create a field of type <strong>Internal Link</strong> in the Grid.</li><li>In the field settings, check that <strong>Link</strong> is enabled among the allowed target types. It is by default.</li><li>Open the field in the row you want and select the flow&#39;s start link (or the form&#39;s share link) from the list.</li></ol><p>The cell now shows a button instead of a text value.</p><h2 id="what-gets-passed-on-click" tabindex="-1">What gets passed on click <a class="header-anchor" href="#what-gets-passed-on-click" aria-label="Permalink to &quot;What gets passed on click&quot;">​</a></h2><p>ApptiveGrid opens the target in an overlay and appends two parameters to its address:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Content</th></tr></thead><tbody><tr><td><code>entityUri</code></td><td>the entry&#39;s full address</td></tr><tr><td><code>entityId</code></td><td>the entry&#39;s ID</td></tr></tbody></table><p>This lets the target — a flow or a form — refer to exactly this entry, instead of starting without context.</p><div class="warning custom-block"><p class="custom-block-title">Not a substitute for pre-filled values</p><p><code>entityUri</code> and <code>entityId</code> identify the entry, they don&#39;t fill in fields. If specific values should already be filled in on the target, combine this with <a href="/en/formulare/vorausgefuellte-links">pre-filled links</a> for a form, or with a step that looks up the ID in the flow.</p></div><h2 id="typical-applications" tabindex="-1">Typical applications <a class="header-anchor" href="#typical-applications" aria-label="Permalink to &quot;Typical applications&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Application</th><th>Flow</th></tr></thead><tbody><tr><td>Kick off an approval process</td><td>A &quot;Approve&quot; button on the entry starts a flow that sets the status</td></tr><tr><td>Follow-up action for exactly this row</td><td>A flow processes, updates, or sends something related to the entry</td></tr><tr><td>Start a guided process tied to the record</td><td>The flow begins with a page that knows which entry it was opened from</td></tr></tbody></table><h2 id="also-works-in-shared-views" tabindex="-1">Also works in shared views <a class="header-anchor" href="#also-works-in-shared-views" aria-label="Permalink to &quot;Also works in shared views&quot;">​</a></h2><p>The button also appears in a <a href="/en/ansichten/ansicht-teilen">shared view</a>. This lets even people without an ApptiveGrid account trigger an action tied to a specific entry — for example, an external person confirming a request.</p><div class="warning custom-block"><p class="custom-block-title">Access to the view isn&#39;t the same as access to the flow</p><p>Whoever sees the button can click it. Check whether the triggered flow itself needs to add its own safeguard for who is actually allowed to carry out the action behind it.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/referenz/spaltentypen#internal-link">Column type reference</a></li><li><a href="/en/flows/trigger">Triggers</a></li><li><a href="/en/formulare/formular-teilen">Share a form</a></li><li><a href="/en/grids/verknuepfungen">Linking Grids</a></li></ul>',22)])])}const u=e(n,[["render",i]]);export{f as __pageData,u as default};
